// Parent restarts the disposable server with the same DATA_DIR before this check.
// The expected path is independently generated by smoke-redesign, not inferred from model output.
import fs from "node:fs";
import path from "node:path";
import { chromium, expect } from "@playwright/test";
import { loadHistory } from "../src/history.ts";
import type { ApplicationDetail, ChatEvent } from "../shared/api.ts";
const origin = process.env.SMOKE_ORIGIN,
  directory = process.env.SMOKE_ARTIFACTS;
if (!origin || !directory || process.env.SMOKE_SYNTHETIC !== "1")
  throw new Error("Disposable loopback instance and SMOKE_ARTIFACTS required");
const url = new URL(origin);
if (!["127.0.0.1", "localhost"].includes(url.hostname))
  throw new Error("Never run against production");
const fixture = JSON.parse(
  fs.readFileSync(path.join(directory, "resume.json"), "utf8"),
) as { id: string; provider: string; expected: string };
const browser = await chromium.launch({
  headless: true,
  ...(process.env.PLAYWRIGHT_EXECUTABLE_PATH
    ? { executablePath: process.env.PLAYWRIGHT_EXECUTABLE_PATH }
    : {}),
});
const page = await browser.newPage({ viewport: { width: 1440, height: 1000 } });
async function api<T>(route: string): Promise<T> {
  const response = await page.request.get(
    `${url.origin}/bewerbung/api${route}`,
  );
  expect(response.ok()).toBe(true);
  return (await response.json()) as T;
}
const events = () =>
  loadHistory<ChatEvent>((after) =>
    api(`/applications/${fixture.id}/events?after=${after}`),
  );
try {
  const before = await events(),
    lastId = before.at(-1)?.id ?? 0;
  expect(
    (await api<ApplicationDetail>(`/applications/${fixture.id}`)).harness
      .provider,
  ).toBe(fixture.provider);
  await page.goto(`${url.origin}/bewerbung/applications/${fixture.id}`);
  const input = page.getByRole("textbox", { name: "Nachricht an Assistent" });
  await expect(input).toBeEditable();
  await expect(
    page.getByRole("button", { name: "Modell und Anbieter wählen" }),
  ).not.toContainText("Modell wählen");
  await input.fill(
    "Resume check: What was the exact application-relative file path you were asked to create in the previously allowed write request? Reply only with that path from our conversation. Do not read files or call any tools.",
  );
  await page
    .getByRole("button", { name: "Nachricht senden", exact: true })
    .click();
  await expect
    .poll(
      async () =>
        (await events())
          .filter((event) => event.id > lastId && event.type === "assistant")
          .map((event) => event.payload.text)
          .join("\n"),
      { timeout: 90000 },
    )
    .toContain(fixture.expected);
  await expect
    .poll(
      async () =>
        (await api<ApplicationDetail>(`/applications/${fixture.id}`)).harness
          .busy,
      { timeout: 30000 },
    )
    .toBe(false);
  const added = (await events()).filter((event) => event.id > lastId);
  expect(added.filter((event) => event.type === "tool")).toHaveLength(0);
  await expect(page.locator('[class*="group/assistant"]').last()).toContainText(
    fixture.expected,
  );
  await expect(input).toHaveText("");
  await page.screenshot({
    path: path.join(directory, "resume-chat.png"),
    animations: "disabled",
  });
  console.log(
    `PASS ${fixture.provider} real native resume after server restart; remembered ${fixture.expected} without tools`,
  );
} finally {
  await browser.close();
}
